"""Data models for SQL pipeline, execution results, repair attempts, and confidence scoring.

Specifications:
- Spec §5 T3 (SQL Execution Engine, Self-repair Loop & Confidence Scorer)
- Plan Task 3: T3-SQL Core Interfaces
"""

from typing import Any, Literal
from pydantic import BaseModel, Field

SqlStatus = Literal["ok", "no_data", "execution_error", "rejected"]


class SqlDraft(BaseModel):
    """Candidate SQL draft generated by LLM or heuristic template."""

    sql: str
    explanation_short: str = ""
    kpi_keys: list[str] = Field(default_factory=list)
    out_of_scope_reason: str | None = None


class SqlExecutionResult(BaseModel):
    """Normalized output of SQL execution on read-only PostgreSQL connection."""

    status: SqlStatus
    sql: str | None = None
    columns: list[str] = Field(default_factory=list)
    rows: list[dict[str, Any]] = Field(default_factory=list)
    row_count: int = 0
    error: str | None = None
    latency_ms: float = 0.0


class RepairAttempt(BaseModel):
    """Record of an attempt in the self-repair loop."""

    attempt_no: int
    sql: str
    stage: Literal["ast", "exec", "ok"]
    status: SqlStatus
    sanitized_error: str | None = None


class ConfidenceBreakdown(BaseModel):
    """Breakdown of confidence score combining similarity, consistency, and plausibility."""

    total: float
    passed_mandatory_gate: bool
    golden_similarity: float
    consistency: float
    plausibility: float
